const robots = $input.all();
const query = $input.item.json.query;

const allocation = robots.map(robot => ({
  robotId: robot.json.robotId,
  robotType: robot.json.robotType,
  batteryLevel: robot.json.batteryLevel,
  status: robot.json.status,
  recommendedTask: robot.json.batteryLevel > 30 ? 'patrol' : 'return_to_base',
  priority: robot.json.batteryLevel < 20 ? 'critical' : 'normal'
}));

return JSON.stringify({ allocation, totalRobots: robots.length });

const robots = $input.all();
const query = $input.item.json.query;

const paths = robots.map(robot => {
  const obstacles = JSON.parse(robot.json.sensorData || '{}').lidar?.obstacles || [];
  return {
    robotId: robot.json.robotId,
    currentPosition: { x: robot.json.positionX, y: robot.json.positionY, z: robot.json.positionZ },
    obstacleCount: obstacles.length,
    pathStatus: obstacles.length > 0 ? 'reroute_required' : 'clear',
    suggestedWaypoints: obstacles.length > 0 ? [{ x: robot.json.positionX + 5, y: robot.json.positionY + 5 }] : []
  };
});

return JSON.stringify({ paths, timestamp: new Date().toISOString() });

const robots = $input.all();
const query = $input.item.json.query;

const activeRobots = robots.filter(r => r.json.status === 'active');
const formationType = query.includes('grid') ? 'grid' : 'adaptive';

const formation = activeRobots.map((robot, index) => ({
  robotId: robot.json.robotId,
  formationPosition: index,
  targetOffset: { x: (index % 3) * 10, y: Math.floor(index / 3) * 10 },
  formationType: formationType
}));

return JSON.stringify({ formation, activeCount: activeRobots.length, pattern: formationType });
